        # prior-wave disjointness W2..W253 (single state: all
        # registered, dynamic registry derive, r511 law)
        for wprev in sorted(w for w in WAVE_CONFIGS if w < 254):
            assert not (w244_a & {WAVE_CONFIGS[wprev]["a_seed_base"] + j
                                 for j in range(A_N)}), f"W254 A hits W{wprev}"
            assert not (w244_b & {WAVE_CONFIGS[wprev]["b_exit_seed_base"] + j
                                  for j in range(B_N)}), f"W254 B hits W{wprev}"
        n3r1_used245 = set(range(70_000, 70_006))
        assert not (w244_a & n3r1_used245) and not (w244_b & n3r1_used245), \
            "W254 bands hit the N3-R1 used-seed band 70_000..70_005 (MSG-183x)"
        assert not (w244_a & lfc_actual12) and not (w244_b & lfc_actual12), \
            "W254 bands must clear the lfc actual draw range"
        assert not (w244_a & options_actual12) and \
            not (w244_b & options_actual12), \
            "W254 bands must clear the options_wave2 actual draw range"
        # band facts (law sec.4 W254 row): A = 1-HOP STAIRCASE-AFFECTS-A
        # walk THIRD consecutive A-hop (the naive continuation
        # 573_901..575_900 REFUSED at naive start -- the registered W253 B band
        # 573_901..574_100 sits INSIDE the naive A window (staircase re-emergence
        # continues to affect A; the W253 prereg sec.5 item5 A-CLEAN-at-naive projection superseded live r587,
        # divergence disclosed); hops=1, A_hop_chain verbatim in the probe receipt,
