        # prior-wave disjointness W2..W282 (single state: all
        # registered, dynamic registry derive, r511 law)
        for wprev in sorted(w for w in WAVE_CONFIGS if w < 283):
            assert not (wnew_a & {WAVE_CONFIGS[wprev]["a_seed_base"] + j
                                 for j in range(A_N)}), f"W283 A hits W" + str(wprev)
            assert not (wnew_b & {WAVE_CONFIGS[wprev]["b_exit_seed_base"] + j
                                  for j in range(B_N)}), f"W283 B hits W" + str(wprev)
        n3r1_used = set(range(70_000, 70_006))
        assert not (wnew_a & n3r1_used) and not (wnew_b & n3r1_used), \
            "W283 bands hit the N3-R1 used-seed band 70_000..70_005 (MSG-183x)"
        assert not (wnew_a & lfc_actual12) and not (wnew_b & lfc_actual12), \
            "W283 bands must clear the lfc actual draw range"
        assert not (wnew_a & options_actual12) and \
            not (wnew_b & options_actual12), \
            "W283 bands must clear the options_wave2 actual draw range"
        # band facts (law sec.4 W283 row): A = 1-HOP STAIRCASE-AFFECTS-A
        # walk THIRTY-THIRD consecutive A-hop (naive continuation
        # 637_701..639_700 REFUSED at naive start by the registered W282 B band;
        # hops=1, A_clean_at_naive_start=false; A base ==
        # registered prior-wave B tail+1 (637_900+1) machine-checkable;
        # B = 1-HOP own-A RESERVATION CASCADE above own-A (naive continuation
        # 637_901..638_100 CLEAN vs registered but lands INSIDE the own-wave A first-clean window);
        # B base == own-A tail+1 (639_900+1) EXACT; THIRTY-FOURTH consecutive above-own-A landing.
